const primaryNavItems = [
  { id: 'editor', label: '工作台', icon: PenLine },
  { id: 'works', label: '我的作品', icon: BookOpen },
  { id: 'relations', label: '人物关系图', icon: Network },
  { id: 'library', label: '素材库', icon: Library },
